#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string abbreviateProduct(int left, int right) {
        const long long LIMIT = 10000000000LL;
        const long long MOD = 100000LL;

        auto mulCap = [&](long long a, long long b) -> long long {
            if (a >= LIMIT) return LIMIT;
            if (b != 0 && a > LIMIT / b) return LIMIT;
            long long res = a * b;
            return res >= LIMIT ? LIMIT : res;
        };

        auto modPow = [&](long long base, int exp) -> long long {
            long long res = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp & 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return res;
        };

        int cnt2 = 0, cnt5 = 0;
        long long tail = 1;
        long long exact = 1;
        long double logSum = 0;

        for (int i = left; i <= right; ++i) {
            logSum += log10l((long double)i);
            int x = i;

            while (x % 2 == 0) {
                cnt2++;
                x /= 2;
            }
            while (x % 5 == 0) {
                cnt5++;
                x /= 5;
            }

            tail = (tail * (x % MOD)) % MOD;
            exact = mulCap(exact, x);
        }

        int zeros = min(cnt2, cnt5);
        int extra2 = cnt2 - zeros;
        int extra5 = cnt5 - zeros;

        tail = (tail * modPow(2, extra2)) % MOD;
        tail = (tail * modPow(5, extra5)) % MOD;

        for (int i = 0; i < extra2; ++i) exact = mulCap(exact, 2);
        for (int i = 0; i < extra5; ++i) exact = mulCap(exact, 5);

        if (exact < LIMIT) {
            return to_string(exact) + "e" + to_string(zeros);
        }

        long double remainingLog = logSum - zeros;
        long double frac = remainingLog - floorl(remainingLog);
        long long first = (long long)(powl(10.0L, frac + 4.0L) + 1e-10L);
        if (first >= 100000) first = 99999;

        string last = to_string(tail);
        while (last.size() < 5) last = "0" + last;

        return to_string(first) + "..." + last + "e" + to_string(zeros);
    }
};
