class Solution {
public:
    vector<string> ambiguousCoordinates(string s) {
        string digits = s.substr(1, s.size() - 2);
        int n = digits.size();
        vector<string> ans;

        auto generate = [](const string& t) {
            vector<string> res;
            int m = t.size();

            if (m == 1 || t[0] != '0') {
                res.push_back(t);
            }

            for (int i = 1; i < m; i++) {
                string left = t.substr(0, i);
                string right = t.substr(i);

                bool validLeft = (left.size() == 1 || left[0] != '0');
                bool validRight = (right.back() != '0');

                if (validLeft && validRight) {
                    res.push_back(left + "." + right);
                }
            }

            return res;
        };

        for (int i = 1; i < n; i++) {
            string leftPart = digits.substr(0, i);
            string rightPart = digits.substr(i);

            vector<string> leftNums = generate(leftPart);
            vector<string> rightNums = generate(rightPart);

            for (const string& left : leftNums) {
                for (const string& right : rightNums) {
                    ans.push_back("(" + left + ", " + right + ")");
                }
            }
        }

        return ans;
    }
};
