#include <bits/stdc++.h>
using namespace std;

class MKAverage {
public:
    MKAverage(int m, int k) {
        this->m = m;
        this->k = k;
        totalSum = 0;
        bitCnt.assign(MAXV + 2, 0);
        bitSum.assign(MAXV + 2, 0);
    }

    void addElement(int num) {
        window.push(num);
        totalSum += num;
        add(bitCnt, num, 1);
        add(bitSum, num, num);

        if ((int)window.size() > m) {
            int old = window.front();
            window.pop();
            totalSum -= old;
            add(bitCnt, old, -1);
            add(bitSum, old, -old);
        }
    }

    int calculateMKAverage() {
        if ((int)window.size() < m) return -1;

        long long smallestK = sumFirst(k);
        long long largestK = totalSum - sumFirst(m - k);
        long long middleSum = totalSum - smallestK - largestK;

        return (int)(middleSum / (m - 2 * k));
    }

private:
    static const int MAXV = 100000;
    int m, k;
    long long totalSum;
    queue<int> window;
    vector<long long> bitCnt, bitSum;

    void add(vector<long long>& bit, int idx, long long delta) {
        for (int i = idx; i <= MAXV; i += i & -i) {
            bit[i] += delta;
        }
    }

    long long query(const vector<long long>& bit, int idx) {
        long long res = 0;
        for (int i = idx; i > 0; i -= i & -i) {
            res += bit[i];
        }
        return res;
    }

    int kth(long long target) {
        int idx = 0;
        int step = 1;
        while ((step << 1) <= MAXV) step <<= 1;

        for (; step > 0; step >>= 1) {
            int next = idx + step;
            if (next <= MAXV && bitCnt[next] < target) {
                idx = next;
                target -= bitCnt[next];
            }
        }

        return idx + 1;
    }

    long long sumFirst(int cnt) {
        if (cnt <= 0) return 0;

        int val = kth(cnt);
        long long cntBefore = query(bitCnt, val - 1);
        long long sumBefore = query(bitSum, val - 1);

        return sumBefore + (long long)(cnt - cntBefore) * val;
    }
};

/**
