class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        int left = 0;
        long long sum = 0;
        int ans = 0;

        auto cost = [&](int l, int r) {
            int L = fruits[l][0];
            int R = fruits[r][0];
            return (R - L) + min(abs(startPos - L), abs(startPos - R));
        };

        for (int right = 0; right < n; right++) {
            sum += fruits[right][1];

            while (left <= right && cost(left, right) > k) {
                sum -= fruits[left][1];
                left++;
            }

            ans = max(ans, (int)sum);
        }

        return ans;
    }
};
