class Solution {
public:
    int maxSumTwoNoOverlap(vector<int>& nums, int firstLen, int secondLen) {
        int n = nums.size();
        vector<int> prefix(n + 1, 0);

        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        auto rangeSum = [&](int l, int r) {
            return prefix[r] - prefix[l];
        };

        auto solve = [&](int len1, int len2) {
            int bestLen1 = 0;
            int ans = 0;

            for (int start2 = len1; start2 + len2 <= n; start2++) {
                bestLen1 = max(bestLen1, rangeSum(start2 - len1, start2));
                ans = max(ans, bestLen1 + rangeSum(start2, start2 + len2));
            }

            return ans;
        };

        return max(solve(firstLen, secondLen), solve(secondLen, firstLen));
    }
};
