class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        int n = flowers.size();
        sort(flowers.begin(), flowers.end());

        int cnt = lower_bound(flowers.begin(), flowers.end(), target) - flowers.begin();

        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + flowers[i];
        }

        long long ans = 0;

        for (int m = cnt; m >= 0; m--) {
            long long costFull = 1LL * (cnt - m) * target - (pref[cnt] - pref[m]);
            if (costFull > newFlowers) continue;

            long long remain = newFlowers - costFull;
            long long beauty = 1LL * (n - m) * full;

            if (m > 0) {
                int lo = 0, hi = target - 1, best = 0;

                while (lo <= hi) {
                    int mid = lo + (hi - lo) / 2;
                    int pos = upper_bound(flowers.begin(), flowers.begin() + m, mid) - flowers.begin();

                    long long need = 1LL * mid * pos - pref[pos];

                    if (need <= remain) {
                        best = mid;
                        lo = mid + 1;
                    } else {
                        hi = mid - 1;
                    }
                }

                beauty += 1LL * best * partial;
            }

            ans = max(ans, beauty);
        }

        return ans;
    }
};
