            for (int j = i + 1; j < n; j++) {
                int x1 = points[i][0], y1 = points[i][1];
                int x2 = points[j][0], y2 = points[j][1];

                if (x1 == x2 || y1 == y2) continue;

                if (pointSet.count(encode(x1, y2)) && pointSet.count(encode(x2, y1))) {
                    ans = min(ans, abs(x1 - x2) * abs(y1 - y2));
                }
            }
        }

        return ans == INT_MAX ? 0 : ans;
    }

private:
