class Solution {
public:
    int minDays(vector<int>& bloomDay, int m, int k) {
        int n = bloomDay.size();
        if (1LL * m * k > n) return -1;

        int low = bloomDay[0], high = bloomDay[0];
        for (int day : bloomDay) {
            low = min(low, day);
            high = max(high, day);
        }

        auto canMake = [&](int days) {
            int bouquets = 0;
            int consecutive = 0;

            for (int bloom : bloomDay) {
                if (bloom <= days) {
                    consecutive++;
                    if (consecutive == k) {
                        bouquets++;
                        consecutive = 0;
                        if (bouquets >= m) return true;
                    }
                } else {
                    consecutive = 0;
                }
            }

            return bouquets >= m;
        };

        int answer = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;

            if (canMake(mid)) {
                answer = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return answer;
    }
};
