        sz.assign(n, 1);

        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        vector<bool> result;

        for (auto& req : requests) {
            int u = req[0], v = req[1];
            int ru = find(u), rv = find(v);

            if (ru == rv) {
                result.push_back(true);
                continue;
            }

            bool canBeFriends = true;

            for (auto& res : restrictions) {
                int x = find(res[0]);
                int y = find(res[1]);

                if ((x == ru && y == rv) || (x == rv && y == ru)) {
                    canBeFriends = false;
                    break;
