            if (canBeFriends) {
                if (sz[ru] < sz[rv]) swap(ru, rv);
                parent[rv] = ru;
                sz[ru] += sz[rv];
                result.push_back(true);
            } else {
                result.push_back(false);
            }
        }

        return result;
    }
