        for (int x : cnt) {
            if (x != 0) return false;
        }

        vector<vector<vector<char>>> dp(
            n + 1, vector<vector<char>>(n, vector<char>(n, false))
        );

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[1][i][j] = (s1[i] == s2[j]);
            }
        }

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len <= n; i++) {
                for (int j = 0; j + len <= n; j++) {
                    for (int split = 1; split < len; split++) {
                        bool noSwap = dp[split][i][j] &&
                                      dp[len - split][i + split][j + split];

                        bool swap = dp[split][i][j + len - split] &&
                                    dp[len - split][i + split][j];

                        if (noSwap || swap) {
                            dp[len][i][j] = true;
                            break;
                        }
                    }
                }
            }
        }

        return dp[n][0][0];
    }
