class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int m = target.size();
        int full = (1 << m) - 1;

        vector<array<int, 26>> counts;
        for (const string& s : stickers) {
            array<int, 26> cnt{};
            for (char c : s) cnt[c - 'a']++;
            counts.push_back(cnt);
        }

        vector<int> dp(1 << m, 1e9);
        dp[0] = 0;

        for (int mask = 0; mask <= full; mask++) {
            if (dp[mask] == 1e9) continue;

            for (auto cnt : counts) {
                int nextMask = mask;

                for (int i = 0; i < m; i++) {
                    if ((nextMask & (1 << i)) == 0) {
                        int ch = target[i] - 'a';
                        if (cnt[ch] > 0) {
                            cnt[ch]--;
                            nextMask |= (1 << i);
                        }
                    }
                }

                if (nextMask != mask) {
                    dp[nextMask] = min(dp[nextMask], dp[mask] + 1);
                }
            }
        }

        return dp[full] == 1e9 ? -1 : dp[full];
    }
};
