#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        pair<int, int> memo[29][29][29];
        bool seen[29][29][29] = {};

        function<pair<int, int>(int, int, int)> dfs = [&](int curN, int a, int b) -> pair<int, int> {
            if (a + b == curN + 1) return {1, 1};

            if (seen[curN][a][b]) return memo[curN][a][b];
            seen[curN][a][b] = true;

            int half = curN / 2;
            int nextN = (curN + 1) / 2;

            set<pair<int, int>> nextStates;
            vector<int> winners;

            function<void(int)> generate = [&](int p) {
                if (p > half) {
                    vector<int> cur = winners;

                    if (curN % 2 == 1) {
                        cur.push_back(half + 1);
                    }

                    sort(cur.begin(), cur.end());

                    int na = -1, nb = -1;
                    for (int i = 0; i < (int)cur.size(); i++) {
                        if (cur[i] == a) na = i + 1;
                        if (cur[i] == b) nb = i + 1;
                    }

                    nextStates.insert({na, nb});
                    return;
                }

                int l = p;
                int r = curN + 1 - p;

                if (l == a || r == a) {
                    winners.push_back(a);
                    generate(p + 1);
                    winners.pop_back();
                } else if (l == b || r == b) {
                    winners.push_back(b);
                    generate(p + 1);
                    winners.pop_back();
                } else {
                    winners.push_back(l);
                    generate(p + 1);
                    winners.pop_back();

                    winners.push_back(r);
                    generate(p + 1);
                    winners.pop_back();
                }
            };

            generate(1);

            int earliest = INT_MAX;
            int latest = 0;

            for (auto [na, nb] : nextStates) {
                auto res = dfs(nextN, na, nb);
                earliest = min(earliest, res.first + 1);
                latest = max(latest, res.second + 1);
            }

            return memo[curN][a][b] = {earliest, latest};
        };

        auto ans = dfs(n, firstPlayer, secondPlayer);
        return {ans.first, ans.second};
    }
};
