#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();

        vector<vector<int>> graph(n);
        for (auto& e : edges) {
            graph[e[0]].push_back(e[1]);
            graph[e[1]].push_back(e[0]);
        }

        vector<vector<int>> coprime(51);
        for (int i = 1; i <= 50; ++i) {
            for (int j = 1; j <= 50; ++j) {
                if (gcd(i, j) == 1) {
                    coprime[i].push_back(j);
                }
            }
        }

        vector<int> ans(n, -1);
        vector<vector<pair<int, int>>> path(51);

        struct Frame {
            int node;
            int parent;
            int depth;
            int state;
        };

        vector<Frame> st;
        st.push_back({0, -1, 0, 0});

        while (!st.empty()) {
            auto [node, parent, depth, state] = st.back();
            st.pop_back();

            if (state == 0) {
                int val = nums[node];
                int bestDepth = -1;
                int bestNode = -1;

                for (int x : coprime[val]) {
                    if (!path[x].empty() && path[x].back().first > bestDepth) {
                        bestDepth = path[x].back().first;
                        bestNode = path[x].back().second;
                    }
                }

                ans[node] = bestNode;
                path[val].push_back({depth, node});

                st.push_back({node, parent, depth, 1});
                for (int nei : graph[node]) {
                    if (nei != parent) {
                        st.push_back({nei, node, depth + 1, 0});
                    }
                }
            } else {
                path[nums[node]].pop_back();
            }
        }

        return ans;
    }
};
