class Solution {
public:
    bool isSolvable(vector<string>& words, string result) {
        int maxLen = 0;
        for (auto &w : words) maxLen = max(maxLen, (int)w.size());
        if ((int)result.size() < maxLen || (int)result.size() > maxLen + 1) return false;

        vector<long long> coef(26, 0);
        vector<bool> seen(26, false), noZero(26, false);

        long long p10[8];
        p10[0] = 1;
        for (int i = 1; i < 8; i++) p10[i] = p10[i - 1] * 10;

        for (string &w : words) {
            if (w.size() > 1) noZero[w[0] - 'A'] = true;
            for (int i = 0; i < (int)w.size(); i++) {
                int c = w[w.size() - 1 - i] - 'A';
                seen[c] = true;
                coef[c] += p10[i];
            }
        }

        if (result.size() > 1) noZero[result[0] - 'A'] = true;
        for (int i = 0; i < (int)result.size(); i++) {
            int c = result[result.size() - 1 - i] - 'A';
            seen[c] = true;
            coef[c] -= p10[i];
        }

        vector<int> chars;
        int leadingCount = 0;
        for (int i = 0; i < 26; i++) {
            if (seen[i]) {
                chars.push_back(i);
                if (noZero[i]) leadingCount++;
            }
        }

        if (chars.size() > 10) return false;
        if (leadingCount > 9) return false;

        sort(chars.begin(), chars.end(), [&](int a, int b) {
            return llabs(coef[a]) > llabs(coef[b]);
        });

        vector<bool> used(10, false);
        int n = chars.size();

        function<bool(int, long long)> dfs = [&](int idx, long long sum) -> bool {
            if (idx == n) return sum == 0;

            long long low = 0, high = 0;
            int minDigit = -1, maxDigit = -1;
            for (int d = 0; d <= 9; d++) {
                if (!used[d]) {
                    minDigit = d;
                    break;
                }
            }
            for (int d = 9; d >= 0; d--) {
                if (!used[d]) {
                    maxDigit = d;
                    break;
                }
            }

            for (int i = idx; i < n; i++) {
                long long c = coef[chars[i]];
                if (c > 0) {
                    low += c * minDigit;
                    high += c * maxDigit;
                } else {
                    low += c * maxDigit;
                    high += c * minDigit;
                }
            }

            if (sum + low > 0 || sum + high < 0) return false;

            int ch = chars[idx];
            for (int d = 0; d <= 9; d++) {
                if (used[d]) continue;
                if (d == 0 && noZero[ch]) continue;

                used[d] = true;
                if (dfs(idx + 1, sum + coef[ch] * d)) return true;
                used[d] = false;
            }

            return false;
        };

        return dfs(0, 0);
    }
};
